def judge(pats, frontier=None):
    """Run the REAL filter judgment on pattern dicts -> parsed items
    ({pattern, gap, current_move, why, confidence, risk}). This is the judge the harness calibrates."""
    def fmt(p):
        rec = f" (recurs across {p['n_repos']} of your repos)" if p.get("n_repos", 1) > 1 else ""
        return f"- {p['pattern']}{rec} — {p.get('evidence', '')}"
    listing = "\n".join(fmt(p) for p in pats)
    if frontier is None:
        frontier = load_frontier()
    return parse_json(call_codex(PROMPT.format(patterns=listing, frontier=frontier)))

def run(n_runs=3):
    golden = load_golden()
    if not golden:
        print("no golden cases — write golden.jsonl first"); return 1

    pats = [{"pattern": g["pattern"], "evidence": g.get("evidence", ""), "n_repos": 1} for g in golden]
    n_runs = max(1, n_runs)
    worst = None  # (rows, passed, must_fail) — most must-fails, then fewest passed
    for _ in range(n_runs):
        rows, passed, must_fail = _one_run(golden, pats)
        if worst is None or must_fail > worst[2] or (must_fail == worst[2] and passed < worst[1]):
            worst = (rows, passed, must_fail)
    rows, passed, must_fail = worst
